// Minimal CDP driver to exercise the cube UI and capture screenshots.
const base = "http://localhost:9222";

async function getTarget() {
  for (let i = 0; i < 40; i++) {
    try {
      const res = await fetch(base + "/json");
      const list = await res.json();
      const page = list.find((t) => t.type === "page" && t.url.includes("8792"));
      if (page) return page;
    } catch {}
    await sleep(250);
  }
  throw new Error("no target");
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const target = await getTarget();
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => {
  ws.onopen = res;
  ws.onerror = rej;
});

let nextId = 1;
const pending = new Map();
const logs = [];
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  } else if (msg.method === "Runtime.consoleAPICalled") {
    logs.push(msg.params.args.map((a) => a.value ?? a.description).join(" "));
  } else if (msg.method === "Runtime.exceptionThrown") {
    logs.push("EXCEPTION: " + JSON.stringify(msg.params.exceptionDetails));
  }
};

function send(method, params = {}) {
  const id = nextId++;
  ws.send(JSON.stringify({ id, method, params }));
  return new Promise((res) => pending.set(id, res));
}

async function evaluate(expression) {
  const r = await send("Runtime.evaluate", {
    expression,
    awaitPromise: true,
    returnByValue: true,
  });
  if (r.result?.exceptionDetails) {
    throw new Error(JSON.stringify(r.result.exceptionDetails));
  }
  return r.result?.result?.value;
}

await send("Runtime.enable");
await send("Page.enable");
await sleep(2500);

// 1) Click R four times -> should return to the solved state.
await evaluate(`
  (async () => {
    const btn = document.querySelector('[data-move="R"]');
    for (let i = 0; i < 4; i++) { btn.click(); await new Promise(r => setTimeout(r, 260)); }
  })()
`);
await sleep(800);
let shot = await send("Page.captureScreenshot", { format: "png" });
await import("node:fs").then((fs) =>
  fs.writeFileSync("/tmp/after_R4.png", Buffer.from(shot.result.data, "base64"))
);

// 2) Scramble then reset.
await evaluate(`document.getElementById('scramble').click()`);
await sleep(4000);
shot = await send("Page.captureScreenshot", { format: "png" });
await import("node:fs").then((fs) =>
  fs.writeFileSync("/tmp/scrambled.png", Buffer.from(shot.result.data, "base64"))
);

await evaluate(`document.getElementById('reset').click()`);
await sleep(900);
shot = await send("Page.captureScreenshot", { format: "png" });
await import("node:fs").then((fs) =>
  fs.writeFileSync("/tmp/reset.png", Buffer.from(shot.result.data, "base64"))
);

console.log("LOGS:", logs.length ? logs : "(none)");
